<template><view class="auth"><view class="hero"><text class="brand-name">小兜芽</text><view class="mascot-stage"><view class="soft-arch"></view><view class="orbit orbit-one"></view><view class="orbit orbit-two"></view><text class="coin-mark mark-left">¥</text><text class="coin-mark mark-right">·</text><image class="mascot" src="../../components/wallet-mascot.png" mode="aspectFit" /></view><view class="motto"><text>把钱给未来，也把自由留给现在。</text><text>先规划，再记账。</text></view><view class="route-board"><view class="route-top"><text>今天的钱，想去哪里？</text><text class="spark">✦</text></view><view class="route"><view class="route-stop"><text class="stop-icon">收</text><text>收进来</text></view><view class="route-line"><text></text></view><view class="route-stop active"><text class="stop-icon">安</text><text>安排好</text></view><view class="route-line"><text></text></view><view class="route-stop"><text class="stop-icon">享</text><text>放心花</text></view></view><view class="route-caption"><text>不必克制生活</text><text>只要知道自己在靠近什么</text></view></view></view><view class="login-card"><view class="login-copy"><text class="title">开始使用</text><text class="muted">微信身份安全登录</text></view><view class="agreement" @click="agreed=!agreed"><view :class="['check',{checked:agreed}]"><text v-if="agreed">✓</text></view><text>我已阅读并同意</text><text class="link" @click.stop="open('/pages/agreement/index')">《用户服务协议》</text><text>和</text><text class="link" @click.stop="open('/pages/privacy/index')">《隐私政策》</text></view><button :class="['wechat-button',{disabled:!agreed}]" @click="wechatLogin">微信一键登录</button></view></view></template>
<script setup>
import { ref } from 'vue'; import { api } from '../../utils/api'
const agreed=ref(false);function open(url){uni.navigateTo({url})}
function wechatLogin(){if(!agreed.value)return uni.showToast({title:'请先阅读并同意相关协议',icon:'none'});uni.login({provider:'weixin',success:async({code})=>{if(!code)return uni.showToast({title:'未取得微信登录凭证',icon:'none'});try{const result=await api('/auth/wechat-login',{method:'POST',data:{code,agreedToTerms:true},skipAuth:true});uni.setStorageSync('accessToken',result.token);uni.setStorageSync('profile',result);uni.switchTab({url:'/pages/index/index'})}catch(error){uni.showToast({title:error?.message||'微信登录失败，请重试',icon:'none'})}},fail:()=>uni.showToast({title:'请在微信小程序中完成登录',icon:'none'})})}
</script>
<style scoped>.auth{min-height:100vh;box-sizing:border-box;background:linear-gradient(180deg,#f2faef 0%,#f8fcf6 54%,#f8fcf6 100%);padding:104rpx 38rpx 70rpx;display:flex;flex-direction:column;justify-content:space-between}.hero{height:650rpx;position:relative}.brand-name{position:absolute;left:0;top:22rpx;color:#354831;font-size:54rpx;font-weight:800;letter-spacing:8rpx}.mascot-stage{position:absolute;top:78rpx;left:0;right:0;height:344rpx;display:flex;justify-content:center;align-items:center}.soft-arch{position:absolute;width:420rpx;height:268rpx;border-radius:220rpx 220rpx 86rpx 86rpx;background:linear-gradient(145deg,#dff0d8,#e9f6e5);transform:translateY(18rpx) rotate(-3deg)}.orbit{position:absolute;border:2rpx solid rgba(112,158,98,.25);border-radius:50%}.orbit-one{width:350rpx;height:158rpx;transform:rotate(-13deg) translateY(12rpx)}.orbit-two{width:286rpx;height:118rpx;border-color:rgba(214,179,103,.34);transform:rotate(22deg) translateY(-8rpx)}.coin-mark{position:absolute;z-index:2;width:42rpx;height:42rpx;border-radius:50%;display:flex;align-items:center;justify-content:center;background:#f2d78d;color:#98752c;font-size:24rpx;font-weight:800;box-shadow:0 8rpx 18rpx rgba(151,117,44,.14)}.mark-left{transform:translate(-188rpx,72rpx) rotate(-12deg)}.mark-right{transform:translate(163rpx,-72rpx);background:#fff;color:#87aa78}.mascot{width:370rpx;height:370rpx;position:relative;z-index:3;filter:drop-shadow(0 20rpx 16rpx rgba(79,115,70,.13))}.motto{position:absolute;top:434rpx;left:0;right:0;display:flex;flex-direction:column;align-items:center;gap:12rpx;color:#354831;font-size:37rpx;font-weight:800;letter-spacing:1rpx}.motto text:last-child{color:#6c8066;font-size:24rpx;font-weight:500;letter-spacing:3rpx}.route-board{position:absolute;left:0;right:0;bottom:0;background:linear-gradient(135deg,#eff8eb,#f9fdf7);border:1rpx solid #dcebd6;border-radius:30rpx;padding:23rpx 26rpx 20rpx;box-shadow:0 14rpx 26rpx rgba(79,115,70,.05)}.route-top{display:flex;justify-content:space-between;color:#58744e;font-size:25rpx;font-weight:800;letter-spacing:1rpx}.spark{color:#c79d3a;font-size:32rpx;line-height:22rpx}.route{display:flex;align-items:center;justify-content:center;margin:18rpx 0 14rpx}.route-stop{display:flex;flex-direction:column;align-items:center;gap:8rpx;color:#6c8066;font-size:23rpx}.stop-icon{width:58rpx;height:58rpx;border-radius:20rpx;background:#fff;color:#58744e;display:flex;align-items:center;justify-content:center;font-size:27rpx;font-weight:800;box-shadow:0 5rpx 12rpx rgba(80,120,70,.06)}.route-stop.active .stop-icon{background:#87aa78;color:#fff;transform:translateY(-7rpx);box-shadow:0 10rpx 16rpx rgba(93,139,80,.22)}.route-stop.active{color:#58744e;font-weight:800}.route-line{width:90rpx;height:2rpx;background:#b8d6af;margin:0 9rpx 27rpx;position:relative}.route-line text{position:absolute;right:-2rpx;top:-5rpx;width:11rpx;height:11rpx;border-radius:50%;background:#87aa78}.route-caption{display:flex;justify-content:center;gap:12rpx;color:#6c8066;font-size:21rpx}.route-caption text:first-child{color:#58744e}.login-card{background:#fff;border:1rpx solid #dcebd6;border-radius:32rpx;padding:34rpx 30rpx;box-shadow:0 16rpx 36rpx rgba(80,120,70,.08)}.login-copy{display:flex;justify-content:space-between;align-items:center;margin-bottom:28rpx}.agreement{display:flex;align-items:center;flex-wrap:wrap;gap:7rpx;font-size:21rpx;line-height:1.6;color:#6c8066;margin-bottom:24rpx}.check{width:26rpx;height:26rpx;border:2rpx solid #a9c5a0;border-radius:8rpx;display:flex;align-items:center;justify-content:center;color:#fff;font-size:20rpx;flex:none}.check.checked{background:#87aa78;border-color:#87aa78}.link{color:#58744e}.wechat-button{width:100%;margin:0;background:#87aa78;color:#fff;border-radius:18rpx;font-size:30rpx;line-height:92rpx}.wechat-button::after{border:0}.wechat-button.disabled{opacity:.55}</style>
